1	// Small pure helpers shared by the screens. Kept free of React and runtime
2	// Convex imports so they stay trivially unit-testable.
3	
4	import type { Doc } from "../convex/_generated/dataModel";
5	
6	export type AuthFlow = "signIn" | "signUp";
7	
8	// What the detail screen needs to render instantly from data the search
9	// results already hold, before its own query answers.
10	export type PersonSnapshot = Pick<
11	  Doc<"people">,
12	  "_id" | "name" | "link" | "context" | "_creationTime"
13	>;
14	
15	// Convex Auth surfaces provider failures as opaque server error strings, so
16	// matching substrings is the only stable-enough signal we have. Wrong email
17	// and wrong password map to one message on purpose: no account enumeration.
18	export function mapAuthError(error: unknown, flow: AuthFlow): string {
19	  const raw = error instanceof Error ? error.message : String(error ?? "");
20	  const message = raw.toLowerCase();
21	
22	  if (message.includes("failed to fetch") || message.includes("network")) {
23	    return "Could not reach the server. Check your connection and try again.";
24	  }
25	  if (flow === "signUp" && message.includes("already exists")) {
26	    return "An account with that email already exists. Try signing in instead.";
27	  }
28	  if (message.includes("invalid password")) {
29	    return "Passwords need at least 8 characters.";
30	  }
31	  if (
32	    message.includes("invalidaccountid") ||
33	    message.includes("invalidsecret")
34	  ) {
35	    return "That email and password do not match.";
36	  }
37	  return "Something went wrong. Please try again.";
38	}
39	
40	// People paste links loosely ("linkedin.com/in/..."). Return an openable
41	// http(s) URL, or null when the text is not a link at all.
42	export function normalizeUrl(raw: string): string | null {
43	  const trimmed = raw.trim();
44	  if (trimmed === "" || /\s/.test(trimmed)) {
45	    return null;
46	  }
47	  if (/^https?:\/\//i.test(trimmed)) {
48	    return trimmed;
49	  }
50	  // Any other explicit scheme (ftp:, mailto:, javascript:) is not openable
51	  // from here; only bare domains get upgraded.
52	  if (/^[a-z][a-z0-9+.-]*:/i.test(trimmed)) {
53	    return null;
54	  }
55	  if (!trimmed.includes(".")) {
56	    return null;
57	  }
58	  return `https://${trimmed}`;
59	}
